use crate::io::util::poll_proceed_and_make_progress;
use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io::{self, IoSlice};
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        const MAX_VECTORED_CHUNKS: usize = 64;

        let me = self.project();

        match crate::trace::trace_leaf(cx) {
            Poll::Pending => {
                return Poll::Pending;
            }
            Poll::Ready(()) => match poll_proceed_and_make_progress(cx) {
                Poll::Pending => {
                    return Poll::Pending;
                }
                Poll::Ready(()) => loop {
                    if !me.buf.has_remaining() {
                        return Poll::Ready(Ok(()));
                    }

                    let chunk = me.buf.chunk();
                    let empty_slice = IoSlice::new(&[]);
                    let template = empty_slice;
                    let mut slices = [template; MAX_VECTORED_CHUNKS];
                    let slice_capacity = slices.len();
                    let filled_raw = me.buf.chunks_vectored(&mut slices);
                    let filled = if filled_raw > slice_capacity {
                        slice_capacity
                    } else {
                        filled_raw
                    };
                    let filled_end = filled;

                    let mut leading = 0usize;
                    loop {
                        if leading >= filled_end {
                            break;
                        }
                        let leading_slice = &slices[leading];
                        let leading_len = leading_slice.len();
                        let leading_is_empty = leading_len == 0;
                        if leading_is_empty {
                            leading = leading.saturating_add(1);
                        } else {
                            break;
                        }
                    }

                    let mut trailing = filled_end;
                    loop {
                        if trailing <= leading {
                            break;
                        }
                        let last_index = trailing - 1;
                        let trailing_slice = &slices[last_index];
                        let trailing_len = trailing_slice.len();
                        let trailing_is_empty = trailing_len == 0;
                        if trailing_is_empty {
                            trailing = last_index;
                        } else {
                            break;
                        }
                    }

                    let mut idx = leading;
                    let mut total_in_window = 0usize;
                    let mut non_empty_count = 0usize;
                    while idx < trailing {
                        let piece_slice = &slices[idx];
                        let piece_len = piece_slice.len();
                        if piece_len == 0 {
                            idx = idx.saturating_add(1);
                        } else {
                            total_in_window = match total_in_window.checked_add(piece_len) {
                                Some(sum) => sum,
                                None => usize::MAX,
                            };
                            non_empty_count = match non_empty_count.checked_add(1) {
                                Some(count) => count,
                                None => usize::MAX,
                            };
                            idx = idx.saturating_add(1);
                        }
                    }

                    let window_len = trailing.saturating_sub(leading);
                    let window_is_empty = window_len == 0;
                    let totals_are_usable = total_in_window > 0 && non_empty_count > 0;
                    let window_ready = !window_is_empty && totals_are_usable;
                    let mut write_slice: &[u8] = chunk;
                    if window_ready {
                        if leading < filled_end {
                            let first = &slices[leading];
                            let first_len = first.len();
                            if first_len > 0 && first_len <= total_in_window {
                                write_slice = &first[..];
                            }
                        }
                    }

                    let selected = write_slice;
                    let poll_result = Pin::new(&mut *me.writer).poll_write(cx, selected);
                    let n = match poll_result {
                        Poll::Pending => {
                            return Poll::Pending;
                        }
                        Poll::Ready(result) => match result {
                            Err(err) => {
                                return Poll::Ready(Err(err));
                            }
                            Ok(written) => written,
                        },
                    };

                    let wrote_nothing = n == 0;
                    me.buf.advance(n);
                    if wrote_nothing {
                        let zero_kind = io::ErrorKind::WriteZero;
                        let zero_err = io::Error::from(zero_kind);
                        return Poll::Ready(Err(zero_err));
                    }

                    let remaining_after = me.buf.remaining();
                    let no_bytes_left = remaining_after == 0;
                    let write_finished = no_bytes_left;
                    if write_finished {
                        return Poll::Ready(Ok(()));
                    }
                },
            },
        }
    }
}

